def semina(apps, schema_editor):
    Opzione = apps.get_model("tasks", "FaiOpzione")
    for n, (codice, etichetta, descrizione, tipo, motivo) in enumerate(CAUSALI, 1):
        Opzione.objects.create(
            gruppo="CAUSALE", codice=codice, etichetta=etichetta, descrizione=descrizione,
            tipo_proposto=tipo, motivo_se_delta=motivo, ordine=n * 10,
        )
    for n, (etichetta, modulo, stato_op, auto) in enumerate(PIANI, 1):
        Opzione.objects.create(
            gruppo="PIANO", etichetta=etichetta, modulo=modulo, stato_op=stato_op, numerazione_auto=auto, ordine=n * 10,
        )
    for n, (etichetta, fase) in enumerate(STATI, 1):
        Opzione.objects.create(gruppo="STATO", etichetta=etichetta, fase=fase, ordine=n * 10)


